-- Installation-local credentials. These tables are never portable business data.
CREATE TABLE pm_host_pins (operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id), operator_version INTEGER NOT NULL, salt TEXT NOT NULL, digest TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, failures INTEGER NOT NULL DEFAULT 0, blocked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pm_host_devices (id TEXT PRIMARY KEY, label TEXT NOT NULL, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, claim_digest TEXT UNIQUE, claim_expires_at INTEGER NOT NULL, lease_digest TEXT UNIQUE, revoked_at INTEGER, operator_id TEXT, operator_version INTEGER, pin_version INTEGER, last_action_at INTEGER NOT NULL DEFAULT 0, generation INTEGER NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, failure_window_at INTEGER NOT NULL DEFAULT 0, blocked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pm_host_security_events (id TEXT PRIMARY KEY, device_id TEXT, operator_id TEXT, action TEXT NOT NULL, at INTEGER NOT NULL);
